package dev.johnmart19.veritycompanion;
import com.google.gson.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.inventory.Slot;

/** Actual vanilla player slots, using the player's existing menu validation for mutations. */
final class InventoryTools {
 static JsonObject row(int slot,ItemStack stack){JsonObject r=new JsonObject();r.addProperty("slot",slot);r.addProperty("group",slot<9?"hotbar":slot<36?"main":slot<40?"armor":"offhand");r.addProperty("id",BuiltInRegistries.ITEM.getKey(stack.getItem()).toString());r.addProperty("count",stack.getCount());r.addProperty("name_untrusted_data",GameTools.clean(stack.getHoverName().getString()));r.addProperty("damage",stack.getDamageValue());return r;}
 static String snapshot(ServerPlayer p){return snapshot(p,new JsonObject());}
 static String snapshot(ServerPlayer p,JsonObject args){int offset=Math.clamp(CompanionBrain.number(args,"offset",0),0,40),limit=Math.clamp(CompanionBrain.number(args,"limit",12),1,12);JsonObject r=new JsonObject();JsonArray items=new JsonArray();int occupied=0,total=0;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(!stack.isEmpty()){if(i>=offset&&i<offset+limit)items.add(row(i,stack));occupied++;total+=stack.getCount();}}r.addProperty("player",p.getGameProfile().getName());r.addProperty("game_mode",p.gameMode.getGameModeForPlayer().getName());r.addProperty("selected_hotbar_slot",p.getInventory().selected);r.addProperty("occupied_slots",occupied);r.addProperty("total_item_count",total);r.addProperty("offset",offset);r.addProperty("next_offset",offset+limit<p.getInventory().getContainerSize()?offset+limit:-1);r.add("items",items);if(!p.containerMenu.getCarried().isEmpty())r.add("cursor_stack",row(-1,p.containerMenu.getCarried()));r.addProperty("coverage","Counts scan all slots, item rows are paginated; follow next_offset. All vanilla player slots: hotbar, main, armor, offhand; cursor separately. Curios, backpack contents, remote storage and custom GUI slots are not scanned. Missing external contents do not mean empty.");return r.toString();}
 static Slot slot(ServerPlayer p,int index){return p.inventoryMenu.slots.stream().filter(s->s.container==p.getInventory()&&s.getContainerSlot()==index).findFirst().orElseThrow(()->new IllegalArgumentException("Unknown own inventory slot"));}
 static String swap(ServerPlayer p,JsonObject args,String human){String s=ToolIntent.normalized(ToolIntent.unaddress(human,Relations.name(p)));if(!allowed(s))throw new IllegalArgumentException("Request moving/swapping your items explicitly");int from=CompanionBrain.number(args,"from_slot",-1),to=CompanionBrain.number(args,"to_slot",-1);Slot a=slot(p,from),b=slot(p,to);ItemStack first=a.getItem().copy(),second=b.getItem().copy();String expected=CompanionBrain.string(args,"expected_id","");if(first.isEmpty()||!BuiltInRegistries.ITEM.getKey(first.getItem()).toString().equals(expected))throw new IllegalArgumentException("Source item changed or expected_id missing; read inventory again");if(!a.mayPickup(p)||!b.mayPickup(p)||!b.mayPlace(first)||!second.isEmpty()&&!a.mayPlace(second)||first.getCount()>b.getMaxStackSize(first)||!second.isEmpty()&&second.getCount()>a.getMaxStackSize(second))throw new IllegalArgumentException("Normal inventory slot rules prevent this swap");a.set(second);b.set(first);p.inventoryMenu.broadcastChanges();p.containerMenu.broadcastChanges();return snapshot(p);}
 static boolean allowed(String input){String s=ToolIntent.normalized(input);return !ToolIntent.excludedGiftText(s)&&!s.contains("?")&&s.matches("(?:переложи|перемести|поменяй местами|поменяй слоты|move|swap) .+");}
}
